const path = require('path')

module.exports = {
  publicPath: '/',
  pluginOptions: {
    mpx: {
      plugin: {
        webRouteConfig: {
          mode: 'hash',
          base: '/'
        },
        srcMode: 'wx'
      }
    }
  },
  configureWebpack: {
    resolve: { alias: { '@': path.resolve(__dirname, 'src') } }
  }
}

item.command:
/bin/zsh -lc "node - <<'NODE'
const fs = require('fs')
const app = fs.readFileSync('outputs/src/app.mpx', 'utf8')
const match = app.match(/<script type=\"application\\/json\">\\s*([\\s\\S]*?)\\s*<\\/script>/)
if ("'!match) throw new Error('"'app JSON block missing')
JSON.parse(match[1])
const checkout = fs.readFileSync('outputs/src/pages/checkout/index.mpx', 'utf8')
const address = fs.readFileSync('outputs/src/pages/address/select.mpx', 'utf8')
const config = fs.readFileSync('outputs/vue.config.js', 'utf8')
const requirements = [
  [checkout.includes(\"mpx.switchTab({ url: '/pages/orders/index' })\"), 'orders must use switchTab'],
  [checkout.includes(\"mpx.reLaunch({ url: '/pages/login/index' })\"), 'login must use reLaunch'],
  [checkout.includes(\"mpx.redirectTo({ url: '/pages/pay/result' })\"), 'pay result must use redirectTo'],
  [checkout.includes('events:') && address.includes('getOpenerEventChannel()'), 'address must use EventChannel'],
  [config.includes(\"publicPath: '/shop/'\"), 'publicPath must be /shop/'],
  [config.includes(\"mode: 'history'\"), 'routing mode must be history'],
  [config.includes(\"base: '/shop/'\"), 'route base must be /shop/']
]
for (const [ok, message] of requirements) if ("'!ok) throw new Error(message)
console.log('"'app JSON and routing constraints OK')
NODE"

